import{_ as e,o as s,c as n,a2 as i}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"Day 6: Creating Custom Layers & Writing Recipes (.bb & .bbappend)","description":"","frontmatter":{},"headers":[],"relativePath":"day6-creating-custom-layers-and-recipes.md","filePath":"day6-creating-custom-layers-and-recipes.md"}'),t={name:"day6-creating-custom-layers-and-recipes.md"};function l(p,a,o,c,r,d){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="day-6-creating-custom-layers-writing-recipes-bb-bbappend" tabindex="-1">Day 6: Creating Custom Layers &amp; Writing Recipes (<code>.bb</code> &amp; <code>.bbappend</code>) <a class="header-anchor" href="#day-6-creating-custom-layers-writing-recipes-bb-bbappend" aria-label="Permalink to &quot;Day 6: Creating Custom Layers &amp; Writing Recipes (\`.bb\` &amp; \`.bbappend\`)&quot;">​</a></h1><p>This module covers creating custom Yocto layers from scratch, understanding recipe syntax (<code>.bb</code>), managing source checksums, writing <code>.bbappend</code> override files, and integrating custom software into your target image.</p><hr><h2 id="_1-why-create-custom-layers" tabindex="-1">1. Why Create Custom Layers? <a class="header-anchor" href="#_1-why-create-custom-layers" aria-label="Permalink to &quot;1. Why Create Custom Layers?&quot;">​</a></h2><p>In Yocto, <strong>never modify core OpenEmbedded or Poky recipes directly</strong>. Upstream layers (<code>meta</code>, <code>meta-poky</code>, <code>meta-ti</code>, <code>meta-raspberrypi</code>) are updated regularly. Any direct edits will be wiped during <code>git pull</code> or version upgrades.</p><h3 id="the-modular-layer-approach" tabindex="-1">The Modular Layer Approach <a class="header-anchor" href="#the-modular-layer-approach" aria-label="Permalink to &quot;The Modular Layer Approach&quot;">​</a></h3><p>Instead, encapsulate all custom recipes, patches, hardware configs, and company-specific applications in a separate custom layer (e.g., <code>meta-custom</code> or <code>meta-product</code>).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meta-custom/</span></span>
<span class="line"><span>├── conf/</span></span>
<span class="line"><span>│   └── layer.conf          # Layer configuration (priority, dependencies, compatible Yocto versions)</span></span>
<span class="line"><span>├── COPYING.MIT             # Layer license</span></span>
<span class="line"><span>├── README                  # Layer description</span></span>
<span class="line"><span>└── recipes-example/</span></span>
<span class="line"><span>    └── myapp/</span></span>
<span class="line"><span>        ├── files/          # Patches, source code files, init scripts</span></span>
<span class="line"><span>        │   ├── myapp.c</span></span>
<span class="line"><span>        │   └── CMakeLists.txt</span></span>
<span class="line"><span>        └── myapp_1.0.bb    # Recipe file</span></span></code></pre></div><hr><h2 id="_2-creating-a-custom-layer-with-bitbake-layers" tabindex="-1">2. Creating a Custom Layer with <code>bitbake-layers</code> <a class="header-anchor" href="#_2-creating-a-custom-layer-with-bitbake-layers" aria-label="Permalink to &quot;2. Creating a Custom Layer with \`bitbake-layers\`&quot;">​</a></h2><p>Yocto provides a helper script to generate standard layer directory templates automatically:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/projects/poky</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create a new layer named meta-custom</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-layer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-custom</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add the new layer to conf/bblayers.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-layer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-custom</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify layer registration</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-layers</span></span></code></pre></div><hr><h2 id="_3-understanding-recipe-bb-syntax-key-variables" tabindex="-1">3. Understanding Recipe (<code>.bb</code>) Syntax &amp; Key Variables <a class="header-anchor" href="#_3-understanding-recipe-bb-syntax-key-variables" aria-label="Permalink to &quot;3. Understanding Recipe (\`.bb\`) Syntax &amp; Key Variables&quot;">​</a></h2><p>A recipe (<code>.bb</code> file) contains instructions for BitBake on how to fetch, patch, compile, package, and install a specific piece of software.</p><h3 id="core-variables-in-a-recipe" tabindex="-1">Core Variables in a Recipe <a class="header-anchor" href="#core-variables-in-a-recipe" aria-label="Permalink to &quot;Core Variables in a Recipe&quot;">​</a></h3><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SUMMARY = &quot;My Custom C Application&quot;</span></span>
<span class="line"><span>DESCRIPTION = &quot;A sample C application demonstrating recipe creation in Yocto.&quot;</span></span>
<span class="line"><span>HOMEPAGE = &quot;https://example.com/myapp&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># License specification (Mandatory)</span></span>
<span class="line"><span>LICENSE = &quot;MIT&quot;</span></span>
<span class="line"><span>LIC_FILES_CHKSUM = &quot;file://\${COMMON_LICENSE_DIR}/MIT;md5=0835ade698e0bcf8506ecda2f7b4f302&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Source code location (local file, Git URL, or Tarball HTTP link)</span></span>
<span class="line"><span>SRC_URI = &quot;file://myapp.c&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Source directory inside build sandbox</span></span>
<span class="line"><span>S = &quot;\${WORKDIR}&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Target installation directory task</span></span>
<span class="line"><span>do_install() {</span></span>
<span class="line"><span>    install -d \${D}\${bindir}</span></span>
<span class="line"><span>    install -m 0755 myapp \${D}\${bindir}</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="key-recipe-variables-explained" tabindex="-1">Key Recipe Variables Explained <a class="header-anchor" href="#key-recipe-variables-explained" aria-label="Permalink to &quot;Key Recipe Variables Explained&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>PN</code></td><td style="text-align:left;">Package Name (derived automatically from recipe filename before <code>_</code>).</td></tr><tr><td style="text-align:left;"><code>PV</code></td><td style="text-align:left;">Package Version (derived automatically from recipe filename after <code>_</code>).</td></tr><tr><td style="text-align:left;"><code>PR</code></td><td style="text-align:left;">Package Revision (e.g., <code>r0</code>, <code>r1</code>). Incremented when modifying build steps.</td></tr><tr><td style="text-align:left;"><code>SRC_URI</code></td><td style="text-align:left;">List of source files, remote URLs, or local patches fetched by <code>do_fetch</code>.</td></tr><tr><td style="text-align:left;"><code>LIC_FILES_CHKSUM</code></td><td style="text-align:left;">MD5 or SHA256 checksum of license text file ensuring compliance.</td></tr><tr><td style="text-align:left;"><code>\${D}</code></td><td style="text-align:left;">Destination directory staging folder representing the rootfs on host.</td></tr><tr><td style="text-align:left;"><code>\${bindir}</code></td><td style="text-align:left;">Standard target binary path (<code>/usr/bin</code>).</td></tr></tbody></table><hr><h2 id="_4-writing-bbappend-files-for-upstream-overrides" tabindex="-1">4. Writing <code>.bbappend</code> Files for Upstream Overrides <a class="header-anchor" href="#_4-writing-bbappend-files-for-upstream-overrides" aria-label="Permalink to &quot;4. Writing \`.bbappend\` Files for Upstream Overrides&quot;">​</a></h2><p>To modify an existing recipe from another layer (e.g., modifying <code>systemd.bb</code> or <code>nginx.bb</code> to add custom config files or patches), write a <strong>Recipe Append file (<code>.bbappend</code>)</strong>.</p><h3 id="naming-rule" tabindex="-1">Naming Rule <a class="header-anchor" href="#naming-rule" aria-label="Permalink to &quot;Naming Rule&quot;">​</a></h3><p>The <code>.bbappend</code> filename must match the original recipe name exactly (e.g., <code>busybox_%.bbappend</code> to match any version of BusyBox).</p><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Structure of meta-custom/recipes-core/busybox/busybox_%.bbappend</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FILESEXTRAPATHS:prepend := &quot;\${THISDIR}/files:&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SRC_URI:append = &quot; file://custom-busybox.cfg&quot;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">FILESEXTRAPATHS PREPEND</p><p>Setting <code>FILESEXTRAPATHS:prepend := &quot;\${THISDIR}/files:&quot;</code> forces BitBake to search your custom layer&#39;s <code>files/</code> directory first before checking upstream layer folders!</p></div><hr><h2 id="_5-inheriting-standard-build-classes" tabindex="-1">5. Inheriting Standard Build Classes <a class="header-anchor" href="#_5-inheriting-standard-build-classes" aria-label="Permalink to &quot;5. Inheriting Standard Build Classes&quot;">​</a></h2><p>Instead of writing manual compilation steps in <code>do_compile()</code>, recipes can inherit standard build system classes:</p><h3 id="autotools-class" tabindex="-1">Autotools Class <a class="header-anchor" href="#autotools-class" aria-label="Permalink to &quot;Autotools Class&quot;">​</a></h3><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inherit autotools</span></span></code></pre></div><p><em>(Automatically executes <code>./configure</code>, <code>make</code>, and <code>make install</code>)</em></p><h3 id="cmake-class" tabindex="-1">CMake Class <a class="header-anchor" href="#cmake-class" aria-label="Permalink to &quot;CMake Class&quot;">​</a></h3><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inherit cmake</span></span></code></pre></div><p><em>(Automatically passes cross-compiler flags to <code>cmake -B build</code> and builds targets)</em></p><h3 id="python-3-class" tabindex="-1">Python 3 Class <a class="header-anchor" href="#python-3-class" aria-label="Permalink to &quot;Python 3 Class&quot;">​</a></h3><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inherit setuptools3</span></span></code></pre></div><p><em>(Automatically compiles and packages Python 3 modules)</em></p><hr><h2 id="_6-testing-your-custom-recipe" tabindex="-1">6. Testing Your Custom Recipe <a class="header-anchor" href="#_6-testing-your-custom-recipe" aria-label="Permalink to &quot;6. Testing Your Custom Recipe&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build custom recipe independently</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add myapp to local.conf</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;IMAGE_INSTALL:append = &quot; myapp&quot;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conf/local.conf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Rebuild root filesystem</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image-minimal</span></span></code></pre></div>`,41)])])}const u=e(t,[["render",l]]);export{b as __pageData,u as default};
